namespace sv_26b18c44ad8f4a3cb6ac60e8ca749c1c.Client.Models;

public record StatusUpdate(DateTime Timestamp, string Status, string Location, string Description);

public record ShipmentDetails(
    string TrackingNumber,
    string Status,
    string Location,
    DateTime EstimatedDelivery,
    IReadOnlyList<StatusUpdate> StatusUpdates);

using sv_26b18c44ad8f4a3cb6ac60e8ca749c1c.Client.Models;

namespace sv_26b18c44ad8f4a3cb6ac60e8ca749c1c.Client.Services;

public interface IShipmentService
{
    Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using sv_26b18c44ad8f4a3cb6ac60e8ca749c1c.Client.Models;
using sv_26b18c44ad8f4a3cb6ac60e8ca749c1c.Client.Services;

namespace sv_26b18c44ad8f4a3cb6ac60e8ca749c1c.Services;

public class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, ShipmentDetails> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["PKG-001"] = new ShipmentDetails(
            TrackingNumber: "PKG-001",
            Status: "In Transit",
            Location: "Chicago, IL",
            EstimatedDelivery: new DateTime(2026, 6, 14),
            StatusUpdates: new List<StatusUpdate>
            {
                new(new DateTime(2026, 6, 9, 8, 0, 0), "Picked Up", "New York, NY", "Package picked up from sender"),
                new(new DateTime(2026, 6, 10, 14, 30, 0), "In Transit", "Philadelphia, PA", "Package departed facility"),
                new(new DateTime(2026, 6, 11, 6, 15, 0), "In Transit", "Chicago, IL", "Package arrived at sorting center"),
            }),

        ["PKG-002"] = new ShipmentDetails(
            TrackingNumber: "PKG-002",
            Status: "Delivered",
            Location: "San Francisco, CA",
            EstimatedDelivery: new DateTime(2026, 6, 10),
            StatusUpdates: new List<StatusUpdate>
            {
                new(new DateTime(2026, 6, 7, 9, 0, 0), "Picked Up", "Seattle, WA", "Package picked up from sender"),
                new(new DateTime(2026, 6, 8, 11, 0, 0), "In Transit", "Portland, OR", "Package in transit"),
                new(new DateTime(2026, 6, 9, 16, 45, 0), "Out for Delivery", "San Francisco, CA", "Package out for delivery"),
                new(new DateTime(2026, 6, 10, 10, 20, 0), "Delivered", "San Francisco, CA", "Package delivered to front door"),
            }),

        ["PKG-003"] = new ShipmentDetails(
            TrackingNumber: "PKG-003",
            Status: "Processing",
            Location: "Dallas, TX",
            EstimatedDelivery: new DateTime(2026, 6, 18),
            StatusUpdates: new List<StatusUpdate>
            {
                new(new DateTime(2026, 6, 11, 7, 0, 0), "Processing", "Dallas, TX", "Order received, preparing shipment"),
            }),
    };

    public async Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        // Simulate a slow backend
        await Task.Delay(1500, ct);

        SeedData.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_26b18c44ad8f4a3cb6ac60e8ca749c1c.Client.Models
@using sv_26b18c44ad8f4a3cb6ac60e8ca749c1c.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<ShipmentTracker> Logger
@implements IDisposable

<PageTitle>Shipment @TrackingNumber</PageTitle>

@if (_loading)
{
    <div class="alert alert-info" role="status">
        <span class="spinner-border spinner-border-sm me-2" aria-hidden="true"></span>
        Loading shipment details for <strong>@TrackingNumber</strong>…
    </div>
}
else if (_errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <p>@_errorMessage</p>
        <button class="btn btn-outline-danger btn-sm mt-2" @onclick="RetryLoad">Retry</button>
    </div>
}
else if (_shipment is null)
{
    <div class="alert alert-warning" role="alert">
        No shipment found for tracking number <strong>@TrackingNumber</strong>.
    </div>
}
else
{
    <h2>Shipment @_shipment.TrackingNumber</h2>
    <dl class="row">
        <dt class="col-sm-3">Status</dt>
        <dd class="col-sm-9">@_shipment.Status</dd>

        <dt class="col-sm-3">Location</dt>
        <dd class="col-sm-9">@_shipment.Location</dd>

        <dt class="col-sm-3">Estimated Delivery</dt>
        <dd class="col-sm-9">@_shipment.EstimatedDelivery.ToString("MMMM d, yyyy")</dd>
    </dl>

    <h4>Status Updates</h4>
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Date/Time</th>
                <th>Status</th>
                <th>Location</th>
                <th>Description</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var update in _shipment.StatusUpdates)
            {
                <tr>
                    <td>@update.Timestamp.ToString("g")</td>
                    <td>@update.Status</td>
                    <td>@update.Location</td>
                    <td>@update.Description</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = default!;

    private ShipmentDetails? _shipment;
    private bool _loading;
    private string? _errorMessage;
    private CancellationTokenSource? _cts;
    private string? _lastLoadedTrackingNumber;

    protected override async Task OnParametersSetAsync()
    {
        // If the tracking number changed (navigation), cancel previous and reload
        if (string.Equals(_lastLoadedTrackingNumber, TrackingNumber, StringComparison.OrdinalIgnoreCase))
            return;

        await LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        // Cancel any in-flight request
        CancelPending();

        _lastLoadedTrackingNumber = TrackingNumber;
        _shipment = null;
        _errorMessage = null;
        _loading = true;

        _cts = new CancellationTokenSource();
        var ct = _cts.Token;

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            // Request was intentionally cancelled (navigation or dispose) — do nothing
            return;
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "Something went wrong while loading shipment details. Please try again.";
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task RetryLoad()
    {
        await LoadShipmentAsync();
    }

    private void CancelPending()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
    }

    public void Dispose()
    {
        CancelPending();
    }
}

